class Logger {
  static #instance;
  #logs = [];

  static getInstance() {
    if (!Logger.#instance) {
      Logger.#instance = new Logger();
    }
    return Logger.#instance;
  }

  log(message) {
    this.#logs.push(message);
  }
}

const a = Logger.getInstance();
const b = Logger.getInstance();
console.log(a === b); // true — نفس النسخة بالضبط

class NotificationFactory {
  createNotification(type) {
    if (type === "email") return new EmailNotification();
    if (type === "sms") return new SmsNotification();
    throw new Error("نوع غير معروف");
  }
}

class EmailNotification { send(msg) { console.log(`Email: ${msg}`); } }
class SmsNotification { send(msg) { console.log(`SMS: ${msg}`); } }

const factory = new NotificationFactory();
const notif = factory.createNotification("email");
notif.send("مرحبا"); // Email: مرحبا

class LightThemeFactory {
  createButton() { return { style: "light-button" }; }
  createCheckbox() { return { style: "light-checkbox" }; }
}

class DarkThemeFactory {
  createButton() { return { style: "dark-button" }; }
  createCheckbox() { return { style: "dark-checkbox" }; }
}

function renderUI(factory) {
  return [factory.createButton(), factory.createCheckbox()];
}

console.log(renderUI(new DarkThemeFactory()));
// [{ style: 'dark-button' }, { style: 'dark-checkbox' }] — عائلة متوافقة، بلا خلط

class PizzaBuilder {
  #pizza = { size: "medium", toppings: [] };
  setSize(size) { this.#pizza.size = size; return this; }
  addTopping(t) { this.#pizza.toppings.push(t); return this; }
  build() { return this.#pizza; }
}

const pizza = new PizzaBuilder().setSize("large").addTopping("جبنة").build();
console.log(pizza); // { size: 'large', toppings: ['جبنة'] }

