// واجهة قديمة غير متوافقة
class OldPrinter {
  printOld(text) { console.log(`[Old] ${text}`); }
}

// الواجهة الموحدة التي يتوقعها الكود الحديث
class PrinterAdapter {
  constructor(oldPrinter) { this.oldPrinter = oldPrinter; }
  print(text) { this.oldPrinter.printOld(text); }
}

const printer = new PrinterAdapter(new OldPrinter());
printer.print("تقرير"); // [Old] تقرير

