class AudioMixer { setLevel(v) { console.log(`مستوى الصوت: ${v}`); } }
class VideoDecoder { decode() { console.log("فك ترميز الفيديو"); } }
class Renderer { render() { console.log("عرض على الشاشة"); } }

class VideoPlayerFacade {
  #mixer = new AudioMixer();
  #decoder = new VideoDecoder();
  #renderer = new Renderer();

  play() {
    this.#decoder.decode();
    this.#mixer.setLevel(70);
    this.#renderer.render();
  }
}

new VideoPlayerFacade().play();

class Subject {
  #observers = [];
  subscribe(fn) { this.#observers.push(fn); }
  notify(data) { this.#observers.forEach((fn) => fn(data)); }
}

const priceAlert = new Subject();
priceAlert.subscribe((price) => console.log(`تنبيه: السعر أصبح ${price}`));
priceAlert.notify(99); // تنبيه: السعر أصبح 99

class CreditCardStrategy { pay(amount) { console.log(`دفع ${amount} ببطاقة`); } }
class PayPalStrategy { pay(amount) { console.log(`دفع ${amount} عبر PayPal`); } }

class Cart {
  constructor(strategy) { this.strategy = strategy; }
  checkout(amount) { this.strategy.pay(amount); }
}

const cart = new Cart(new PayPalStrategy());
cart.checkout(50); // دفع 50 عبر PayPal

class Handler {
  setNext(h) { this.next = h; return h; }
  handle(req) { if (this.next) return this.next.handle(req); console.log("لا يوجد معالج"); }
}

class AuthHandler extends Handler {
  handle(req) { if (!req.token) return console.log("مرفوض"); super.handle(req); }
}

class LoggerHandler extends Handler {
  handle(req) { console.log(`طلب من ${req.user}`); super.handle(req); }
}

const auth = new AuthHandler();
auth.setNext(new LoggerHandler());
auth.handle({ user: "سارة", token: "abc" }); // طلب من سارة

